  pixFill(c,GL[1],x0+E,gTop+E,x1-E,gB-E);
  pixFill(c,GL[2],x0+E,gB-2*E,x1-E,gB-E);
  pixFill(c,GL[0],x0+E,gTop+E,x0+E+Math.max(2*E,w.w*0.2),gB-2*E);
